type Pattern = { re: RegExp; t: { es: string; en: string; fr: string; zh: string } };
const p = (re: RegExp, en: string, fr: string, zh: string): Pattern => ({ re, t: { es: '', en, fr, zh } });

/** Frases de estos módulos con datos variables; `{n}` es el grupo capturado n. */
